#!/usr/bin/env python3
"""Derive and verify the selected installed sd-bus C ABI; native headers only enter compiler -include probes."""
import argparse,hashlib,json,re,subprocess,tempfile
from pathlib import Path
FUNCTIONS='''sd_bus_new sd_bus_set_address sd_bus_set_bus_client sd_bus_set_exit_on_disconnect sd_bus_start sd_bus_close sd_bus_unref sd_bus_get_fd sd_bus_get_events sd_bus_get_timeout sd_bus_process sd_bus_call_async sd_bus_add_match_async sd_bus_slot_unref sd_bus_message_ref sd_bus_message_unref sd_bus_message_new_method_call sd_bus_message_get_sender sd_bus_message_get_error sd_bus_message_get_errno sd_bus_message_append sd_bus_message_append_array sd_bus_message_open_container sd_bus_message_close_container sd_bus_message_read sd_bus_message_read_array sd_bus_message_enter_container sd_bus_message_exit_container sd_bus_message_at_end sd_bus_message_skip sd_bus_message_peek_type'''.split()
OPAQUE=['sd_bus','sd_bus_message','sd_bus_slot']
CONSTANTS='SD_BUS_TYPE_ARRAY SD_BUS_TYPE_VARIANT SD_BUS_TYPE_STRUCT SD_BUS_TYPE_DICT_ENTRY SD_BUS_TYPE_STRING SD_BUS_TYPE_BOOLEAN SD_BUS_TYPE_BYTE SD_BUS_TYPE_INT32 SD_BUS_TYPE_UINT64'.split()
def run(cmd,source=None):
 r=subprocess.run(cmd,input=source,capture_output=True,text=True,timeout=60)
 if r.returncode:raise RuntimeError((cmd,r.stderr))
 return r.stdout

def printer(prefix=''):
 s=['template<class T> void signature(char const*name,T){std::printf("signature %s %s\\n",name,__PRETTY_FUNCTION__);}','int main(){',f'std::printf("layout %zu %zu %zu %zu %zu\\n",sizeof({prefix}sd_bus_error),alignof({prefix}sd_bus_error),__builtin_offsetof({prefix}sd_bus_error,name),__builtin_offsetof({prefix}sd_bus_error,message),__builtin_offsetof({prefix}sd_bus_error,_need_free));']
 s += [f'signature("{name}",&{prefix}{name});' for name in FUNCTIONS]
 s += [f'std::printf("constant {name} %lld\\n",static_cast<long long>({prefix}{name}));' for name in CONSTANTS]
 return '\n'.join(s+['}'])
def main():
 p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);p.add_argument('--check',action='store_true');a=p.parse_args();root=a.root.resolve();flags=['g++','-std=c++26','-Werror']
 text=run(['g++','-E','-P','-x','c++','-include','systemd/sd-bus.h','-'],source='')
 fields=re.findall(r'typedef struct sd_bus_error \{([^{}]*)\} sd_bus_error;',text);assert len(fields)==1
 decl=['struct '+name+';' for name in OPAQUE];decl+=['struct sd_bus_error {'+fields[0]+'};','using sd_bus_message_handler_t = int (*)(sd_bus_message*,void*,sd_bus_error*);']
 for name in FUNCTIONS:
  matches=re.findall(r'(?:^|;)\s*([^;{}]*?\b'+name+r'\([^;{}]*?\))\s*;',text,re.M)
  assert len(matches)==1,(name,matches)
  value=' '.join(matches[0].split());value=re.sub(r'\buint64_t\b','std::uint64_t',value);value=re.sub(r'\bsize_t\b','std::size_t',value)
  decl.append('extern "C" '+value+';')
 with tempfile.TemporaryDirectory(prefix='sd-bus-abi-',dir=root) as td:
  td=Path(td);s=td/'native.cpp';exe=td/'native';s.write_text(printer());run(flags+['-include','cstdio','-include','cstddef','-include','systemd/sd-bus.h',str(s),'-lsystemd','-o',str(exe)]);native=run([str(exe)])
  constants={line.split()[1]:int(line.split()[2]) for line in native.splitlines() if line.startswith('constant ')}
  body='namespace nexus::platform::sd_bus_abi {\n'+'\n'.join(decl+[f'inline constexpr int {name}={value};' for name,value in constants.items()])+'\n}\n'
  s=td/'generated.cpp';exe=td/'generated';s.write_text(body+printer('nexus::platform::sd_bus_abi::'));run(flags+['-include','cstdio','-include','cstddef','-include','cstdint',str(s),'-lsystemd','-o',str(exe)]);generated=run([str(exe)]).replace('nexus::platform::sd_bus_abi::','')
  assert native==generated,{'native':native,'generated':generated}
 dependencies=run(['g++','-M','-x','c++','-include','systemd/sd-bus.h','-'],source='').replace('\\\n',' ').split(':',1)[1].split()
 profile={'target':'Linux x86-64 LP64 glibc + installed libsystemd','native_generated_result':native,'headers':{str(Path(x).resolve()):hashlib.sha256(Path(x).read_bytes()).hexdigest() for x in dependencies},'functions':FUNCTIONS,'constants':constants}
 js=json.dumps(profile,indent=2,sort_keys=True)+'\n';sha=hashlib.sha256(js.encode()).hexdigest()
 module='// Generated by scripts/resolved-boundary.py; no textual includes.\n// Native profile SHA-256: '+sha+'\n#if !defined(__linux__) || !defined(__x86_64__) || !defined(__LP64__)\n#error "sd-bus boundary verified for Linux x86-64 LP64 glibc only"\n#endif\nexport module nexus.platform.sd_bus_abi;\nimport std;\n'+body.replace('namespace nexus::platform::','export namespace nexus::platform::',1)
 for relative,data in {'src/platform/sd_bus_abi.cppm':module,'scripts/resolved-boundary.json':js}.items():
  file=root/relative
  if a.check:assert file.read_text()==data,relative
  else:file.parent.mkdir(exist_ok=True,parents=True);file.write_text(data)
 print(len(FUNCTIONS),'C signatures, error struct layout and',len(CONSTANTS),'constants match native; profile',sha)
if __name__=='__main__':main()
